import { test } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 50, C: 33.33, D: 100, E: 100.01, F: 0.1 }
const pricing = { priceOf: async (sku) => prices[sku] }

async function totalFor(items) {
  const server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  try {
    const res = await fetch(`http://localhost:${server.address().port}/orders`, {
      method: 'POST',
      body: JSON.stringify({ items }),
    })
    assert.equal(res.status, 201)
    return (await res.json()).total
  } finally {
    server.close()
  }
}

// These pin CURRENT behaviour (10% off when subtotal > 100, result floored to whole euros).
test('small order has no discount', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 3 }]), 30)
})

test('subtotal of exactly 100 gets no discount', async () => {
  assert.equal(await totalFor([{ sku: 'D', qty: 1 }]), 100)
})

test('subtotal just over 100 is discounted', async () => {
  assert.equal(await totalFor([{ sku: 'E', qty: 1 }]), 90)
})

test('larger order gets 10% off', async () => {
  assert.equal(await totalFor([{ sku: 'B', qty: 3 }]), 135)
})

test('multiple items are summed before discount', async () => {
  assert.equal(await totalFor([{ sku: 'B', qty: 2 }, { sku: 'A', qty: 5 }]), 135)
})

// Floor, not round: 133.32 * 0.9 = 119.988 -> 119 (customer loses almost 1 euro)
test('discounted total is floored, not rounded', async () => {
  assert.equal(await totalFor([{ sku: 'C', qty: 4 }]), 119)
})

test('fractional totals are floored without discount too', async () => {
  assert.equal(await totalFor([{ sku: 'F', qty: 15 }]), 1)
})
EOF
npm test 2>&1 | tail -20

